import type { ContactKind } from '@/lib/supabase/types/database'

// Pure naming helpers for contacts. Kept import-free (type-only) so they can
// be unit-tested and used from client components.

export const KIND_LABELS: Record<ContactKind, string> = {
  person: 'Person',
  organization: 'Organization',
}

export type ContactNameFields = {
  name: string | null
  first_name: string | null
  last_name: string | null
}

/**
 * Map a single typed-in name to the contacts naming columns. display_name is
 * generated by the database, so writes never set it: organizations store the
 * name as `name`; people are split into first name (first word) and last name
 * (the rest). A one-word person name is just a first name.
 */
export function nameFieldsFor(kind: ContactKind, fullName: string): ContactNameFields {
  const trimmed = fullName.trim().replace(/\s+/g, ' ')
  if (kind === 'organization') return { name: trimmed || null, first_name: null, last_name: null }
  const [first, ...rest] = trimmed.split(' ')
  return { name: null, first_name: first || null, last_name: rest.length ? rest.join(' ') : null }
}

/** Normalize a kind coming from a form or an older client ('individual'). */
export function parseContactKind(value: unknown): ContactKind {
  return value === 'person' || value === 'individual' ? 'person' : 'organization'
}

/** Lower-cased, trimmed email, or null when blank. */
export function normalizeEmail(email: string | null | undefined): string | null {
  const e = email?.trim().toLowerCase()
  return e ? e : null
}
